themeCSS:
.node rect, .node polygon, .node path, .node circle { stroke-width: 1.5px; }
.nodeLabel, .label foreignObject div, .edgeLabel { font-family: 'Red Hat Text', Helvetica, Arial, sans-serif !important; color: #151515 !important; }
.cluster-label text, .cluster-label span { font-family: 'Red Hat Text', Helvetica, Arial, sans-serif !important; font-weight: 500; color: #151515 !important; }
.edgePath .path, .flowchart-link { stroke: #4d4d4d !important; stroke-width: 1.5px !important; stroke-linecap: square; }
.marker path { fill: #4d4d4d !important; stroke: #4d4d4d !important; }
.actor { stroke-width: 1.5px !important; }
